"""Language features reached through the CLI: one compact input per feature
cluster (floorplan joins, icons, chart formats/time axes/bands, routing
strategies, link operators, drawing features, layout knobs, colour and
expression functions), each compiled to SVG and printed by desugar."""

import pytest

from conftest import Case

